<script setup lang="ts">
import { ui } from "../ui"
import DateTime from './DateTime.vue'
import { computed,ref,onMounted,onUnmounted } from 'vue'
import { RouterLink,onBeforeRouteLeave,onBeforeRouteUpdate } from 'vue-router'
import { api,notify } from '../composables/api'
import { useCollaborationAction } from '../composables/collaboration'
import type { AlertConfiguration,EmailDestination,TestDeliveryOperation } from '../types'
const props=defineProps<{testing?:boolean;setup?:boolean}>(),emit=defineEmits<{saved:[];verified:[]}>(),config=ref<AlertConfiguration|null>(null),error=ref(''),loading=ref(false),saving=ref(false),editor=ref(false),name=ref(''),email=ref(''),enabled=ref(false),editing=ref<EmailDestination|null>(null),replacing=ref<EmailDestination|null>(null),selected=ref<string[]>([]),confirm=ref(false),operation=ref<TestDeliveryOperation|null>(null),polling=ref(false)
const editorBaseline=ref('');const dirty=computed(()=>editor.value&&editorBaseline.value!==JSON.stringify([name.value,email.value,enabled.value]));
function confirmLeave(){return !dirty.value||window.confirm('Discard this unsaved recipient draft?')}
onBeforeRouteLeave(confirmLeave);onBeforeRouteUpdate((to,from)=>to.path===from.path||confirmLeave());defineExpose({confirmLeave});
const unload=(e:BeforeUnloadEvent)=>{if(dirty.value){e.preventDefault();e.returnValue=''}};
const perform=useCollaborationAction();let timer:ReturnType<typeof setTimeout>|undefined,disposed=false
const recipients=computed(()=>config.value?.connections.filter(c=>selected.value.includes(c.id))??[])
async function load(){loading.value=true;try{config.value=await api<AlertConfiguration>('/alerting');config.value.connections=config.value.connections.filter(c=>c.provider==='email');selected.value=selected.value.filter(id=>config.value?.connections.some(c=>c.id===id&&c.enabled&&!c.disconnected))}catch(e){error.value=e instanceof Error?e.message:'Email destinations unavailable.'}finally{loading.value=false}}
onMounted(()=>{window.addEventListener('beforeunload',unload);load()});onUnmounted(()=>{disposed=true;clearTimeout(timer);window.removeEventListener('beforeunload',unload)})
function open(c:EmailDestination|null=null,replace=false){if(!confirmLeave())return;editing.value=replace?null:c;replacing.value=replace?c:null;name.value=c?.name??'';email.value=replace?'':c?.email??'';enabled.value=replace?false:c?.enabled??false;editor.value=true;editorBaseline.value=JSON.stringify([name.value,email.value,enabled.value]);error.value=''}
async function reloadDraft(){if(!confirmLeave())return;const id=editing.value?.id;editor.value=false;await load();if(id){const c=config.value?.connections.find(c=>c.id===id);if(c)open(c)}}
async function save(){saving.value=true;error.value='';try{await perform('/alerting/email'+(editing.value?'/'+editing.value.id:''),editing.value?'PATCH':'POST',{name:name.value,enabled:enabled.value,...(editing.value?{version:editing.value.version}:{email:email.value,...(replacing.value?{replaces:replacing.value.id,replaces_version:replacing.value.version}:{})})});editor.value=false;notify('Email recipient configuration saved. Duplicate addresses reuse their canonical destination.');await load();emit('saved')}catch(e){error.value=e instanceof Error?e.message:'Recipient could not be saved.'}finally{saving.value=false}}
async function disconnect(c:EmailDestination){if(!window.confirm('Disconnect this recipient? Pending work is cancelled; history is retained.'))return;saving.value=true;try{await perform('/alerting/email/'+c.id,'DELETE',{version:c.version});await load()}catch(e){error.value=e instanceof Error?e.message:'Disconnect failed.'}finally{saving.value=false}}
async function status(attempt=0){if(disposed||!operation.value)return;try{operation.value=await api<TestDeliveryOperation>('/alerting/tests/'+operation.value.id);const waiting=operation.value.items.some(d=>['pending','processing','retrying'].includes(d.status));if(waiting&&attempt<14){polling.value=true;timer=setTimeout(()=>status(attempt+1),2000)}else{polling.value=false;await load();if(operation.value.items.length&&operation.value.items.every(d=>d.status==='sent'))emit('verified')}}catch(e){polling.value=false;error.value=e instanceof Error?e.message:'Test status could not be read.'}}
async function test(){saving.value=true;error.value='';clearTimeout(timer);try{const result=await perform<{id:string}>('/alerting/tests','POST',{connections:selected.value});confirm.value=false;operation.value={id:result.id,items:[],queue_asynchronous:config.value?.queue_asynchronous??false};await status()}catch(e){error.value=e instanceof Error?e.message:'Test intent could not be queued.'}finally{saving.value=false}}
</script>
<template><section :class="ui('$all', '$section', 'email-destinations')"><div :class="ui('$all', '$div', 'section-heading')"><h2 :class="ui('$all', '$h2')">{{testing?'Test email delivery':'Email destinations'}}</h2><button v-if="!testing" :class="ui('$all', '$button', 'button')" @click="open()">Add recipient</button></div><p :class="ui('$all', '$p', 'help')">One canonical recipient is one destination. Host mailer configuration controls transport; SMTP credentials never enter this dashboard.</p><p v-if="config" :class="ui('$all', '$p', 'help')">Host mailer: {{config.mailer}}. Tests use this configured transport.</p><div v-if="error" :class="ui('$all', '$div', 'notice danger')" role="alert">{{error}}<button :class="ui('$all', '$button', 'button')" @click="reloadDraft">Reload configuration</button></div><p :class="ui('$all', '$p')" v-if="loading" role="status">Loading recipients…</p><form v-if="editor" :class="ui('$all', '$form', 'email-editor')" @submit.prevent="save"><h3 :class="ui('$all', '$h3')">{{replacing?'Replace recipient target':editing?'Edit label and availability':'Add email recipient'}}</h3><label :class="ui('$all', '$label', 'field')">Display label<input :class="ui('$all', '$input')" v-model="name" required maxlength="120" :disabled="saving"></label><label :class="ui('$all', '$label', 'field')">Recipient email<input :class="ui('$all', '$input')" v-model="email" type="email" required :readonly="!!editing" :disabled="saving" placeholder="oncall@example.test"></label><label :class="ui('$all', '$label', 'checkbox-row')"><input :class="ui('$all', '$input')" v-model="enabled" type="checkbox" :disabled="saving">Enabled for delivery</label><p :class="ui('$all', '$p', 'help')">{{editing?'The target is immutable. Replace it to change the address.':'Addresses are trimmed and lowercased; plus tags and dots are preserved.'}} {{replacing?'Replacing disconnects the old target. Edit rules explicitly to select the new target; old pending work never moves.':''}}</p><div :class="ui('$all', '$div', 'inline-actions')"><button :class="ui('$all', '$button', 'button primary')" :disabled="saving">Save recipient</button><button :class="ui('$all', '$button', 'button')" type="button" :disabled="saving" @click="confirmLeave()&&(editor=false)">Cancel</button></div></form><div v-if="config" :class="ui('$all', '$div', 'email-list')"><article v-for="c in config.connections" :key="c.id" :class="ui('$all', '$article', 'email-entry')"><header :class="ui('$all', '$header')"><label :class="ui('$all', '$label', 'checkbox-row')"><input :class="ui('$all', '$input')" v-model="selected" :value="c.id" type="checkbox" :disabled="!c.enabled||c.disconnected||saving">{{c.name}}</label><span :class="ui('$all', '$span', 'badge')">{{c.disconnected?'Disconnected':c.enabled?'Enabled':'Disabled'}}</span></header><p :class="ui('$all', '$p')">{{c.email??c.display}} <span v-if="c.state==='unreadable'" :class="ui('$all', '$span', 'field-error')">Address could not be decrypted.</span></p><dl :class="ui('$all', '$dl', 'email-observations')"><div :class="ui('$all', '$div')"><dt :class="ui('$all', '$dt')">Last transport acceptance</dt><dd :class="ui('$all', '$dd')"><DateTime :class="ui('$all', '$DateTime')" :value="c.last_accepted_at"/></dd></div><div :class="ui('$all', '$div')"><dt :class="ui('$all', '$dt')">Last test</dt><dd :class="ui('$all', '$dd')">{{c.last_test_outcome??'Unverified'}} · <DateTime :class="ui('$all', '$DateTime')" :value="c.last_test_at"/></dd></div><div :class="ui('$all', '$div')"><dt :class="ui('$all', '$dt')">Failed history items</dt><dd :class="ui('$all', '$dd')">{{c.failed_count}}</dd></div></dl><div v-if="!testing" :class="ui('$all', '$div', 'inline-actions')"><button :class="ui('$all', '$button', 'button')" :disabled="saving" @click="open(c)">Edit label / availability</button><button :class="ui('$all', '$button', 'button')" :disabled="saving" @click="open(c,true)">Replace recipient</button><button v-if="!c.disconnected" :class="ui('$all', '$button', 'button')" :disabled="saving" @click="disconnect(c)">Disconnect</button></div></article><p :class="ui('$all', '$p')" v-if="!config.connections.length">No email recipients configured. Add one, then explicitly test it.</p></div><div :class="ui('$all', '$div', 'inline-actions spacing')"><button :class="ui('$all', '$button', 'button primary')" :disabled="!selected.length||saving||polling||!config?.enabled" @click="confirm=true">Send synthetic test</button><RouterLink to="/alerts/history" :class="ui('$all', '$a', 'text-link')">Delivery history</RouterLink></div><div v-if="confirm" :class="ui('$all', '$div', 'notice warning')"><div :class="ui('$all', '$div')"><strong :class="ui('$all', '$strong')">Confirm test recipients</strong><ul :class="ui('$all', '$ul')"><li :class="ui('$all', '$li')" v-for="c in recipients" :key="c.id">{{c.name}} · {{c.email??c.display}}</li></ul><p :class="ui('$all', '$p')">Queue one labeled synthetic email per recipient through the host mailer. This does not enable automatic rules.</p><div :class="ui('$all', '$div', 'inline-actions')"><button :class="ui('$all', '$button', 'button')" :disabled="saving" @click="test">Confirm queued test</button><button :class="ui('$all', '$button', 'button')" :disabled="saving" @click="confirm=false">Cancel test</button></div></div></div><section v-if="operation" :class="ui('$all', '$section', 'test-delivery-result')" role="status"><h3 :class="ui('$all', '$h3')">{{polling?'Checking queued test…':'Test delivery result'}}</h3><p v-if="!operation.queue_asynchronous" :class="ui('$all', '$p', 'help')">A supported asynchronous worker is not configured. Durable intent remains pending; the explicit delivery CLI command can process it deliberately.</p><ul :class="ui('$all', '$ul')"><li :class="ui('$all', '$li')" v-for="d in operation.items" :key="d.id"><RouterLink :class="ui('$all', '$a')" :to="'/alerts/history/'+d.id">{{d.destination_name}} · {{d.status}}</RouterLink><span :class="ui('$all', '$span')" v-if="d.reason"> · {{d.reason}}</span></li></ul><p :class="ui('$all', '$p', 'help')">Sent means the host transport accepted this test. It does not prove inbox receipt or future automatic delivery.</p><button v-if="!polling" :class="ui('$all', '$button', 'button')" @click="status()">Refresh test status</button></section></section></template>
